-- Do not edit by hand - edit shim_source.lua and re-run the builder.
--==============================================================================
local EMBEDDED_CODE = {
["cindy.lua"] = [=[
local cindy = {
	_VERSION     = 'cindy 0.1.2',
	_LICENSE     = 'WTFPL, http://www.wtfpl.net',
	_URL         = 'https://github.com/megagrump/cindy',
	_DESCRIPTION = 'True Colors for LÖVE 11',
