	poem_scroll = nil
	
	--[[
    if s1 then
		Font.unload(s1)
		s1 = nil
	end
	if y1 then
		Font.unload(y1)
		y1 = nil
	end
	if n1 then
		Font.unload(n1)
		n1 = nil
	end
	if m1 then
		Font.unload(m1)
		m1 = nil
	end
	]]
	if type(poembg) == "number" then Graphics.freeImage(poembg) end
	poembg = nil
	if not x or x == 1 then
		audioUpdate('5')
	elseif x == 0 then
		audioUpdate('0')
	end
end
