["loader/characters.lua"] = [=[
function loadCharacter(set, chrName)
	local chr = chrName
	local lr = {'',''}
	local asset1
	local asset2
	local asset3
	
	-- Prefer explicit name; fall back to table identity; then to set._chr
	if not chr or chr == '' then
		if set == s_Set then
			chr = 'sayori'
		elseif set == y_Set then
			chr = 'yuri'
		elseif set == n_Set then
			chr = 'natsuki'
		elseif set == m_Set then
			chr = 'monika'
		elseif set and set._chr then
			chr = set._chr
		end
	end
	if not chr then
		print('[DDLC-LOVE] loadCharacter: unknown character set')
		return nil, nil, nil
	end
	if set then set._chr = chr end
	
	if set.a == '1' then
		lr = {'1l','1r'}
	elseif set.a == '2' then
		lr = {'1l','2r'}
	elseif set.a == '3' and set ~= y_Set then
		lr = {'2l','1r'}
	elseif (set.a == '3' and set == y_Set) or (set.a == '4' and set ~= y_Set) then
		lr = {'2l','2r'}
	elseif set.a == '1b' then
		lr = {'1bl','1br'}
	elseif set.a == '2b' then
		lr = {'1bl','2br'}
	elseif set.a == '3b' and set ~= y_Set then
		lr = {'2bl','1br'}
	elseif (set.a == '3b' and set == y_Set) or (set.a == '4b' and set ~= y_Set) then
		lr = {'2bl','2br'}
	elseif (set.a == '4' and set == y_Set) or set.a == '5' then
		lr = {'3',''}
	elseif set.a == '5a' then
		lr = {'3a',''}
	elseif (set.a == '4b' and set == y_Set) or set.a == '5b' then
		lr = {'3b',''}
	elseif set.a == '5c' then
		lr = {'3c',''}
	elseif set.a == '5d' then
		lr = {'3d',''}
	elseif set.a then
		lr = {set.a,''}
	end
	
	local function loadLayer(file)
		local img = lgnewImage('assets/images/'..chr..'/'..file..'.png')
		if img and img.missing then
			-- drop path-cache miss and retry once
			imagePathCache['assets/images/'..chr..'/'..file..'.png'] = nil
			img = lgnewImage('assets/images/'..chr..'/'..file..'.png')
		end
		return img
	end
	asset1 = loadLayer(lr[1])
	if lr[2] ~= '' then
		asset2 = loadLayer(lr[2])
	end
	if set.b ~= '' then
		asset3 = loadLayer(set.b)
	end
	local tag = chr .. '|' .. tostring(set.a) .. '|' .. tostring(set.b)
	if asset1 and not asset1.missing then asset1._chrTag = tag end
	if asset2 and not asset2.missing then asset2._chrTag = tag end
	if asset3 and not asset3.missing then asset3._chrTag = tag end
	return asset1, asset2, asset3
end

function loadSayori()
	unloadSayori()
	s_Set._chr = 'sayori'
	sl, sr, s_a = loadCharacter(s_Set, 'sayori')
end

function unloadSayori()
	if sl then Graphics.freeImage(sl) end
	if sr then Graphics.freeImage(sr) end
	if s_a then Graphics.freeImage(s_a) end
	sl, sr, s_a = nil
end

function loadYuri()
	unloadYuri()
	y_Set._chr = 'yuri'
	yl, yr, y_a = loadCharacter(y_Set, 'yuri')
end

function unloadYuri()
	if yl then Graphics.freeImage(yl) end
	if yr then Graphics.freeImage(yr) end
	if y_a then Graphics.freeImage(y_a) end
	yl, yr, y_a = nil
end

function loadNatsuki()
	unloadNatsuki()
	n_Set._chr = 'natsuki'
	nl, nr, n_a = loadCharacter(n_Set, 'natsuki')
end

function unloadNatsuki()
	if nl then Graphics.freeImage(nl) end
	if nr then Graphics.freeImage(nr) end
	if n_a then Graphics.freeImage(n_a) end
	nl, nr, n_a = nil
end

function loadMonika()
	unloadMonika()
	m_Set._chr = 'monika'
	ml, mr, m_a = loadCharacter(m_Set, 'monika')
end

function unloadMonika()
	if ml then Graphics.freeImage(ml) end
	if mr then Graphics.freeImage(mr) end
	if m_a then Graphics.freeImage(m_a) end
	ml, mr, m_a = nil
end

function loadAll()
	loadSayori()
	loadNatsuki()
	loadYuri()
	loadMonika()
end

function unloadAll(x)
	if x == 'poemgame' then
		if type(s_sticker_1) == "number" then Graphics.freeImage(s_sticker_1) end
		if type(s_sticker_2) == "number" then Graphics.freeImage(s_sticker_2) end
		if type(y_sticker_1) == "number" then Graphics.freeImage(y_sticker_1) end
		if type(y_sticker_2) == "number" then Graphics.freeImage(y_sticker_2) end
		if type(n_sticker_1) == "number" then Graphics.freeImage(n_sticker_1) end
		if type(n_sticker_2) == "number" then Graphics.freeImage(n_sticker_2) end
		if type(eyes) == "number" then Graphics.freeImage(eyes) end
		s_sticker_1 = nil
		s_sticker_2 = nil
		y_sticker_1 = nil
		y_sticker_2 = nil
		n_sticker_1 = nil
		n_sticker_2 = nil
		eyes = nil
		collectgarbage()
		collectgarbage()
	else
		unloadSayori()
		unloadYuri()
		unloadNatsuki()
		unloadMonika()
	end
end
