["menu.lua"] = [=[
local menu_items
local cX
local cY
local getcompare = {}
local pagenum = 1
local savenum = {}
local itemnames = {}
local chch
local cpick
local menu_fadeout
local menu_mtimer = 0
local save_oset = {x={366,652,938},y={250,485}}
local save_date = {}
local save_bpic = {}
local save_hoverpos = {}
local sxp = 0
local history_scr = -39
local dversionx = 1180
local ca1 = {70,140,210}
local xpsc = 400
local ypsc = {35,65,95,125}
local hold = 0
local scanbuttons = {'up','down','left','right'}
local cond = {}
local hold = {0,0,0,0}
menu_alpha = 0

function savepicLoad(i)
	local bgname = 'black'
	local ok, res = pcall(function()
		return loadstring('return save'..chch..'.bg1')()
	end)
	if ok and res and res ~= '' then bgname = tostring(res) end
	-- Prefer dedicated save thumbnail; fall back to full background art
	local thumb = lgnewImage('assets/images/bg/save/'..bgname..'.jpg')
	if not thumb or thumb.missing then
		thumb = lgnewImage('assets/images/bg/'..bgname..'.jpg')
	end
	if not thumb or thumb.missing then
		thumb = lgnewImage('assets/images/bg/black.jpg')
	end
	save_bpic[i] = thumb
end

function savepicFree()
	for i = 1, #save_bpic do
		if type(save_bpic[i]) == "number" then
			Graphics.freeImage(save_bpic[i])
			save_bpic[i] = nil
		end
	end
end

function menu_enable(m)
	menu_enabled = true
	menu_type = m
	
	if menu_type == 'savegame' or menu_type == 'loadgame' or menu_type == 'title' then
		save_bpic = {}
		for i = 1, 6 do
			if pagenum > 1 then	
				chch = ((pagenum-1)*6)+i
			else
				chch = i
			end
			if chch < 10 then
				chch = '0'..chch
			end
			savenum[i] = chch
			if love.filesystem.getInfo('save'..chch..'-'..persistent.ptr..'.sav') then
				local status = loaddatainfo(chch)
				if status then
					print(chch)
					save_date[i] = loadstring('return save'..chch..'.date')()
					if menu_type ~= 'title' then savepicLoad(i) end
				end
			else
				save_date[i] = 'empty slot'
			end
			
		end
	end
	
	menutext = ''
	if menu_type == 'mainyesno' then
		menutext = tr.menuhelp[9]
		itemnames = {tr.menuitem[1],tr.menuitem[2]}
		
	elseif menu_type == 'quityesno' then
		menutext = tr.menuhelp[10]
		itemnames = {tr.menuitem[1],tr.menuitem[2]}
	
	elseif menu_type == 'title' then
		itemnames = {'','','','',''}
		
	elseif menu_type == 'settings' then
		itemnames = {'Text Speed','Auto-Forward Time','Characters','Language','Master Volume','Music Volume','Sound Volume','Back'}
	
	elseif menu_type == 'characters' then
		itemnames = {tr.menuitem[3]..'monika.chr',tr.menuitem[3]..'natsuki.chr',tr.menuitem[3]..'sayori.chr',tr.menuitem[3]..'yuri.chr',tr.menuitem[4]}
	
	elseif menu_type == 'pause' then
		itemnames = {'','','','','','','',''}
		
	elseif menu_type == 'dialog' then 
		itemnames = {''}
		
	elseif menu_type == 'savegame' or menu_type == 'loadgame' then
		itemnames = {'','','','','',''}
		
	elseif menu_type == 'help' or menu_type == 'history' then
		itemnames = {}
		
	elseif menu_type == 'language' then
		itemnames = lang_names
		menutext = tr.selectlang
	end
	
	if menu_type == 'choice' then
		menu_items = #choices + 1
	else
		menu_items = #itemnames + 1
	end
	
	sxp = 0
	for i = 1, #save_date do
		if save_date[i] ~= 'empty slot' then
			sxp = sxp + 1
		end
	end
	
	-- Always start on New Game; player chooses Load/Settings themselves
	if menu_type == 'title' or menu_type == 'pause' then
		m_select(2)
	else
		m_select(2)
	end
end

function menu_drawstuff(a)
	if a == 'dialog' then
		lg.setColor(255,189,225,255)
		lg.rectangle('fill',400,180,480,360)
		lg.setColor(255,230,244,255)
		lg.rectangle('fill',410,190,460,340)
		lg.setColor(255,189,225,255)
	elseif a == 'overlay' then
		lg.setColor(255,255,255,menu_alpha)
		lg.draw(menu_bg,posX,posY)
		lg.draw(gui.mmenu)
		if menu_previous == 'pause' then
			lg.draw(gui.gamebuttons)
		elseif menu_previous == 'title' then
			lg.draw(gui.mainbuttons)
			lg.draw(gui.newgame)
		end
	end
end

function menu_draw()
	lg.setColor(255,255,255,menu_alpha)
	
	if menu_type == 'title' then
		lg.draw(gui.check,-670+titlebg_ypos,(cY/1.2)+280)
		
	elseif menu_type == 'choice' or menu_type == 'mainyesno' or menu_type == 'quityesno' or menu_type == 'language' then
		if menu_type == 'mainyesno' or menu_type == 'quityesno' then
			lg.draw(menu_bg,posX,posY)
		end
		if menu_type == 'choice' then
			lg.setColor(255,255,255,255)
			lg.draw(textbox,230,565)
			outlineText(menutext,260,593,'c_disp')
		else
			lg.setColor(255,255,255,128)
			lg.rectangle('fill',0,0,1280,725)
			menu_drawstuff('dialog')
			lg.setColor(0,0,0)
			lg.print(menutext,430,190)
		end
		for i = 1, 8 do
			if menu_items >= i+1 then
				lg.setColor(255,189,255,menu_alpha)
				lg.rectangle('fill',435, 195+(50*i),410,42)
				lg.setColor(255,230,244,menu_alpha)
				lg.rectangle('fill',440, 200+(50*i),400,32)
			end
		end
		lg.setColor(255,255,255,menu_alpha/2.5)
		lg.rectangle('fill',435,195+(50*(m_selected-1)),410,42)
		lg.setColor(0,0,0,menu_alpha)
		for i = 1, 8 do
			if menu_items >= i+1 and menu_type == 'choice' and choices[i] and m_selected ~= i+1 then
				lg.print(choices[i],440,200+(50*i))
			elseif menu_items >= i+1 and itemnames[i] and m_selected ~= i+1 then
				lg.print(itemnames[i],440,200+(50*i))
			end
		end		
		if menu_items >= m_selected and menu_type == 'choice' and choices[m_selected-1] then
			outlineText(choices[m_selected-1],440,150+(50*m_selected),'m_selected')
		elseif menu_items >= m_selected and itemnames[m_selected-1] then
			outlineText(itemnames[m_selected-1],440,150+(50*m_selected),'m_selected')
		end
		lg.draw(gui.check,408,200+(50*(m_selected-1)))
		
	elseif menu_type == 'dialog' then
		lg.setColor(255,255,255,128)
		lg.rectangle('fill',0,0,1280,725)
		menu_drawstuff('dialog')
		lg.setColor(255,189,255,255)
		lg.rectangle('fill',435,245,410,42)
		lg.setColor(255,230,244,255)
		lg.rectangle('fill',440,250,400,32)
		lg.setColor(255,255,255,menu_alpha/2.5)
		lg.rectangle('fill',435,245,410,42)
		lg.setColor(0,0,0,255)
		lg.print(menutext,430,190)
		outlineText(tr.missing[2],440,250,'m_selected')
		lg.draw(gui.check,408,250)
		
		
	elseif menu_type == 'pause' then
		lg.draw(gui.gmenu)
		lg.draw(gui.gamebuttons)
		if gui.gamemenu then
			lg.draw(gui.gamemenu)
		end
		lg.draw(gui.check,50,(cY/1.2)+240)
		
	elseif menu_type == 'help' then
		lg.setColor(255,255,255,menu_alpha)
		lg.draw(menu_bg,posX,posY)
		lg.setColor(255,189,225,menu_alpha)
		lg.rectangle('fill',100,50,1080,620)
		lg.setColor(255,230,244,menu_alpha)
		lg.rectangle('fill',120,70,1040,580)
		lg.setColor(0,0,0,menu_alpha)
		lg.print(menutext,140,90)
		local keys = {}
		if global_os == 'LOVE-WrapLua' then
			if not lv1lua.confirm then
				keys = {'Cross, (L)','Start','(R)','Triangle','Circle','Select'}
			else
				keys = {'Circle, (L)','Start','(R)','Square','Cross','Select'}
			end
		elseif g_system == "Switch" then
			keys = {'(A), (L)','(+)','(R)','(Y)','(B)','(-)'}
		else
			keys = {'Space, Return', '3', '2', '1', 'Esc', '4'}
		end
		lg.setColor(0,0,0)
		lg.print('Key Bindings:',160,120)
		lg.print(keys[1]..tr.menuhelp[1],160,160)
		lg.print(keys[2]..tr.menuhelp[2],160,190)
		lg.print(keys[3]..tr.menuhelp[3],160,220)
		lg.print(keys[4]..tr.menuhelp[4],160,250)
		lg.print(keys[5]..tr.menuhelp[5],160,280)
		lg.print(keys[6]..tr.menuhelp[12],160,310)
		lg.print(tr.menuhelp[6],160,360)
		lg.print(tr.menuhelp[7]..savedir,160,390)
		
	elseif menu_type == 'savegame' or menu_type == 'loadgame' then
		menu_drawstuff('overlay')
		if menu_type == 'loadgame' then
			gui.gamemenu = gui.load
			lg.draw(gui.load)
		elseif menu_type == 'savegame' then
			gui.gamemenu = gui.save
			lg.draw(gui.save)
		end
		if m_selected >= 2 and m_selected <= 4 then
			save_hoverpos.x = save_oset.x[m_selected-1]
			save_hoverpos.y = save_oset.y[1]
		else
			save_hoverpos.x = save_oset.x[m_selected-4]
			save_hoverpos.y = save_oset.y[2]
		end
		for i = 1, 6 do
			local apx={x=0,y=0}
			if i >= 1 and i <= 3 then
				apx.x = save_oset.x[i]
				apx.y = save_oset.y[1]
			else
				apx.x = save_oset.x[i-3]
				apx.y = save_oset.y[2]
			end
			lg.setColor(236,182,229,menu_alpha)
			lg.rectangle("fill",apx.x+10,apx.y-40,256,144)
			lg.setColor(255,255,255,menu_alpha)
			if save_bpic[i] and not save_bpic[i].missing then
				local iw = save_bpic[i].w or 256
				local ih = save_bpic[i].h or 144
				if iw < 2 then iw = 256 end
				if ih < 2 then ih = 144 end
				lg.draw(save_bpic[i], apx.x+10, apx.y-40, 0, 256/iw, 144/ih)
			end
			lg.setColor(0,0,0,menu_alpha)
			lg.print(savenum[i]..': '..save_date[i],(apx.x+10),(apx.y+110))
		end
		if savenumber == 61 then
			lg.print(menutext,366,138)
		else
			lg.print('Page '..pagenum,751,138)
			lg.setColor(170,170,170,255)
			lg.print("1\t2\t3\t4\t5\t6\t7\t8\t9\t10",627,660)
		end
		
		-- Selection frame only (do not cover the preview image)
		lg.setColor(255,255,255,220)
		lg.rectangle("line",save_hoverpos.x+8,save_hoverpos.y-42,260,148)
		lg.setColor(255,180,220,90)
		lg.rectangle("line",save_hoverpos.x+6,save_hoverpos.y-44,264,152)
		
	elseif menu_type == 'settings' then
		menu_drawstuff('overlay')
		lg.setColor(255,255,255)
		gui.gamemenu = gui.settings
		lg.draw(gui.settings)
		lg.draw(gui.setbuttons)
		-- Visible leave-settings control
		lg.setColor(255,189,225,menu_alpha)
		lg.rectangle('fill', 40, 650, 220, 40)
		lg.setColor(255,230,244,menu_alpha)
		lg.rectangle('fill', 44, 654, 212, 32)
		lg.setColor(0,0,0,menu_alpha)
		lg.print('Back (LCtrl)', 55, 658)
		local hv = {x=0,y=0}
		if m_selected <= 5 then
			hv.x = 340
		else
			hv.x = 790
		end
		if m_selected == 2 or m_selected == 6 then
			hv.y = 344
		elseif m_selected == 3 or m_selected == 7 then
			hv.y = 412
		elseif m_selected == 4 or m_selected == 8 then
			hv.y = 480
		elseif m_selected == 5 then
			hv.y = 548
		end
		lg.draw(gui.scrbarh,368,378)
		lg.draw(gui.scrbarh,368,446)
		lg.draw(gui.scrbarh,818,378)
		lg.draw(gui.scrbarh,818,446)
		lg.draw(gui.scrbarh,818,514)
		lg.draw(gui.scrhover,((settings.textspd-50)*1.7)+368,378)
		lg.draw(gui.scrhover,((settings.autospd-1)*24.29)+368,446)
		lg.draw(gui.scrhover,(settings.masvol*3.4)+818,378)
		lg.draw(gui.scrhover,(settings.bgmvol*3.4)+818,446)
		lg.draw(gui.scrhover,(settings.sfxvol*3.4)+818,514)
		lg.draw(gui.check,hv.x,hv.y)
		lg.setColor(0,0,0)
		lg.print(settings.textspd,525,340)
		lg.print(settings.autospd,625,410)
		lg.print(settings.masvol..'%',1020,340)
		lg.print(settings.bgmvol..'%',1005,410)
		lg.print(settings.sfxvol..'%',1010,480)
		lg.print(dvertype..'\n'..dversion,dversionx,650)
		
	elseif menu_type == 'history' then
		menu_drawstuff('overlay')
		gui.gamemenu = gui.history
		lg.draw(gui.history)
		lg.setColor(0,0,0)
		
		for i = 1, #history do
			local temptext = wrap(history[i],70)
			local ypos = 3600+(history_scr*75)-(i*120)
			
			if g_system == 'PSP' then
				xpsc = 360
			end
			if global_os == 'LOVE-WrapLua' then
				lg.print(temptext,xpsc,ypos)
			else
				outlineText(temptext,xpsc,ypos,'c_disp')
			end
		end
	else
		menu_drawstuff('overlay')
		lg.setColor(255,189,225,menu_alpha)
		for i = 1, 8 do
			if menu_items >= i+1 then lg.rectangle('fill',360, 110+(50*i),200,32) end
		end
		lg.setColor(0,0,0,menu_alpha)
		lg.draw(gui.check,cX+200,cY)
		lg.print(menutext,340,90)
	end
	
	
	if menu_type == 'characters' then
		lg.setColor(255,255,255,menu_alpha)
		lg.draw(gui.gamemenu)
		lg.setColor(0,0,0,menu_alpha)
		for i = 1, 8 do
			if menu_items >= i+1 and itemnames[i] then
				lg.print(itemnames[i],362,110+(50*i))
			end
		end
	end
	
	if persistent.act2[2] < 1 and menu_mchance == 50 and persistent.ptr == 2 then
		lg.setColor(255,255,255,255)
		lg.draw(menu_bg_m)
	end
end

function menu_update()
	if menu_fadeout then
		menu_alpha = math.max(menu_alpha - dt*1000, 0)
		if menu_alpha == 0 then
			menu_enabled = false
			menu_type = nil
			menu_previous = nil
			menu_fadeout = false
		end
	else
		menu_alpha = math.min(menu_alpha + dt*1000, 255)
	end
	
	if persistent.act2[2] < 1 and menu_mchance == 50 and persistent.ptr == 2 then
		menu_mtimer = menu_mtimer + dt
		if menu_mtimer > 0.5 then
			persistent.act2[2] = 1
			savepersistent()
		end
	end
	
	if menu_type == 'history' then
		if g_system == 'Switch' then
			if joystick:isGamepadDown('dpdown') and history_scr > -39 then
				history_scr = history_scr - dt*15
			elseif joystick:isGamepadDown('dpup') and history_scr < 2 then
				history_scr = history_scr + dt*15
			end
		else
			if love.keyboard.isDown('down') and history_scr > -39 then
				history_scr = history_scr - dt*15
			elseif love.keyboard.isDown('up') and history_scr < 2 then
				history_scr = history_scr + dt*15
			end
		end
	end
	
	for i = 1, #scanbuttons do
		if g_system == 'Switch' then
			cond[i] = joystick:isGamepadDown('dp'..scanbuttons[i])
		else
			cond[i] = love.keyboard.isDown(scanbuttons[i])
		end
		if cond[i] then
			hold[i] = hold[i] + dt
			if hold[i] >= 0.35 then
				if hold[i] > 0.45 then
					love.keypressed(scanbuttons[i])
					hold[i] = 0.35
				end
			end
		else
			hold[i] = 0
		end
	end
end

function menu_confirm()
	if menu_type == 'title' or menu_type == 'pause' or menu_type == 'choice' or menu_type == 'dialog' then
		sfxplay2(sfx1)
	end
	
	if menu_type == 'title' then --title screen options
		menu_previous = 'title'
		m_selected2 = m_selected
		
		if m_selected == 2 then --new game
			bg1 = 'black'
			if player ~= '' or dvertype == 'Test' then --go straight to new game
				changeState('game',1)
			elseif player == '' then --keyboard input for player name
				if global_os == 'LOVE-WrapLua' or g_system == 'Switch' then
					local input = {}
					input["type"] = "standard"
					input["header"] = "Enter Player Name"
					input["subheader"] = ""
					input["hint"] = "Enter Player Name"
					input["isPassword"] = false
					love.keyboard.setTextInput(input)
				else
					-- Roblox port: skip on-screen keyboard, use default name
					player = (player ~= '' and player) or "Player"
					changeState('game',1)
				end
			end
			menu_previous = nil
		
		elseif m_selected == 3 then --load game
			pagenum = 1
			menu_enable('loadgame')
			
		elseif m_selected == 4 then --settings
			pagenum = 1
			menu_enable('settings')
		
		elseif m_selected == 5 then --help
			menu_enable('help')
			
		elseif m_selected == 6 then --quit
			menu_enable('quityesno')
		end
		
	elseif menu_type == 'loadgame' and persistent.chr.m ~= 2 then --load game confirm
		savenumber = savenum[m_selected-1]
		if love.filesystem.getInfo('save'..savenumber..'-'..persistent.ptr..'.sav') then
			changeState('game',2)
		else
			menu_enable(menu_previous)
		end
	elseif menu_type == 'loadgame' and persistent.chr.m == 2 then
		menu_enable(menu_previous)
		
	elseif menu_type == 'savegame' and persistent.chr.m ~= 2 then  --save game confirm 
		savenumber = savenum[m_selected-1]
		if menu_previous2 == 'choice' then
			scriptJump(cl-1)
			choices = {''}
			menu_previous2 = nil
		end
		savegame()
		savedatainfo(savenumber)
		menu_enable('savegame')
	elseif menu_type == 'savegame' and persistent.chr.m == 2 then
		if chapter == 30 then 
			menutext = tr.menuhelp[8]
			savenumber = 61
		else
			menu_enable(menu_previous)
		end
	
	elseif menu_type == 'pause' then --pause menu options
		menu_previous = menu_type
		m_selected2 = m_selected
		
		if m_selected == 2 then
			menu_enable('history')
		elseif m_selected == 3 then
			pagenum = 1
			menu_enable('savegame')
		elseif m_selected == 4 then
			pagenum = 1
			menu_enable('loadgame')
		elseif m_selected == 5 then
			if persistent.chr.m == 2 then
				menu_fadeout = true
			else
				menu_enable('mainyesno')
			end
		elseif m_selected == 6 then
			pagenum = 1
			menu_enable('settings')
		elseif m_selected == 7 then
			menu_enable('help')
		elseif m_selected == 8 then
			menu_enable('quityesno')
		elseif m_selected == 9 then
			menu_fadeout = true
		end
		
	elseif menu_type == 'mainyesno' then
		if m_selected == 2 then
			changeState('title')
		elseif m_selected == 3 then
			menu_enable('pause')
		end
		
	elseif menu_type == 'quityesno' then
		if m_selected == 2 then
			love.event.quit()
		elseif m_selected == 3 then
			menu_enable(menu_previous)
		end
		
	elseif menu_type == 'settings' then
		if m_selected == 4 then
			menu_enable('characters')
		elseif m_selected == 5 and g_system ~= 'Switch' then
			changeState('language')
		elseif m_selected == 9 then
			-- Back
			savesettings()
			local prev = menu_previous
			if not prev or prev == 'settings' then
				if state == 'title' or state == 'splash' or state == 'splash2' then
					prev = 'title'
				else
					prev = 'pause'
				end
			end
			menu_previous = nil
			menu_enable(prev)
		elseif m_selected >= 2 and m_selected <= 8 then
			-- value rows use left/right; confirm is a no-op (keeps selection)
		end
		
	elseif menu_type == 'characters' then
		if m_selected == 2 then
			if persistent.chr.m < 2 or (persistent.chr.m == 2 and chapter == 30) then
				persistent.chr.m = 0
			end
		elseif m_selected == 4 then
			if persistent.ptr == 0 then
				persistent.chr.s = 0
			end
		elseif m_selected == 6 then
			if persistent.ptr == 0 then
				persistent.chr.s = 1
			end
			if persistent.chr.m < 2 then
				persistent.chr.m = 1
			end
		end
		savepersistent()
		menu_enable(menu_previous)
		
	elseif menu_type == 'choice' then
		if choicepick ~= '' then
			scriptJump(cl+1)
			menu_fadeout = true
		end
		
	elseif menu_type == 'dialog' then
		scriptJump(cl+1)
		menu_fadeout = true
		
	elseif menu_type == 'language' then
		settings.lang = lang_codes[m_selected-1]
		savesettings()
		if splashx then
			love.event.quit()
		else
			l_timer = 99
			changeState('load')
		end
	end
end

function m_select(arg)
	if arg then m_selected = arg end
	if m_selected <= 5 and menu_type == 'choice' then 
		choicepick = choices[m_selected-1]
	elseif menu_type ~= 'choice' then cpick = itemnames[m_selected-1] end
	cX = 135
	cY = 110+(50*(m_selected-1))
end

function menu_keypressed(key)
	if key == 'down' then
		if menu_type ~= 'history' and menu_type ~= 'savegame' and menu_type ~= 'loadgame' then
			sfxplay2(sfx2)
		end
		if menu_type == 'savegame' or menu_type == 'loadgame' then
			if m_selected <= 4 then
				m_selected = m_selected + 3
			else
				m_selected = m_selected - 3
			end
		elseif m_selected <= menu_items-1 then
			m_selected = m_selected + 1
		else
			m_selected = 2
		end
		m_select()
		
	elseif key == 'up' then
		if menu_type ~= 'history' and menu_type ~= 'savegame' and menu_type ~= 'loadgame'  then
			sfxplay2(sfx2)
		end
		if menu_type == 'savegame' or menu_type == 'loadgame' then
			if m_selected >= 5 and m_selected <= 7 then
				m_selected = m_selected - 3
			else
				m_selected = m_selected + 3
			end
		elseif m_selected >= 3 then
			m_selected = m_selected - 1
		else
			m_selected = menu_items
		end
		m_select()
		
	elseif key == 'a' then
		menu_confirm()
		
	elseif key == 'b' then
		if menu_type == 'history' then
			history_scr = -39
		elseif menu_type == 'settings' then
			savesettings()
		end
		if menu_type == 'pause' then
			menu_fadeout = true
		elseif menu_type == 'settings' or menu_type == 'characters' or menu_type == 'savegame' or menu_type == 'loadgame' or menu_type == 'help' or menu_type == 'history' or menu_type == 'mainyesno' or menu_type == 'quityesno' then
			local prev = menu_previous
			if not prev or prev == menu_type then
				if state == 'title' or state == 'splash' or state == 'splash2' then
					prev = 'title'
				else
					prev = 'pause'
				end
			end
			menu_previous = nil
			savepicFree()
			if prev == 'title' then
				menu_enable('title')
			elseif prev == 'pause' then
				menu_enable('pause')
			else
				menu_enable(prev)
			end
			if m_selected2 then
				m_selected = m_selected2
				m_select()
				m_selected2 = nil
			end
			return
		elseif menu_type ~= 'title' and menu_type ~= 'pause' and menu_type ~= 'choice' and menu_type ~= 'language' then
			menu_enable(menu_previous or 'pause')
		end
		savepicFree()
		if m_selected2 then
			m_selected = m_selected2
			m_select()
			m_selected2 = nil
		end
		menu_previous = nil
		
	elseif key == 'left' then
		if menu_type == 'savegame' or menu_type == 'loadgame' then
			if (m_selected == 2 or m_selected == 5) and pagenum > 1 then
				pagenum = pagenum - 1
				m_selected2 = m_selected
				menu_enable(menu_type)
				if m_selected2 == 2 then
					m_selected = 4
				elseif m_selected2 == 5 then
					m_selected = 7
				end
			elseif m_selected > 2 and m_selected ~= 5 then
				m_selected = m_selected - 1
			end
			m_select()
		elseif menu_type == 'settings' then
			if cpick == 'Text Speed' then
				if settings.textspd > 250 then
					settings.textspd = 250
				elseif settings.textspd > 50 then
					settings.textspd = settings.textspd - 25
				end
			elseif cpick == 'Auto-Forward Time' and settings.autospd > 1 then
				settings.autospd = settings.autospd - 1
			elseif cpick == 'Master Volume' and settings.masvol > 0 then
				settings.masvol = settings.masvol - 10
			elseif cpick == 'Music Volume' and settings.bgmvol > 0 then
				settings.bgmvol = settings.bgmvol - 10
			elseif cpick == 'Sound Volume' and settings.sfxvol > 0 then
				settings.sfxvol = settings.sfxvol - 10
			end
		end
		game_setvolume()
		
	elseif key == 'right' then
		if menu_type == 'savegame' or menu_type == 'loadgame' then
			if (m_selected == 4 or m_selected == 7) and pagenum < 10 then
				pagenum = pagenum + 1
				m_selected2 = m_selected
				menu_enable(menu_type)
				if m_selected2 == 4 then
					m_selected = 2
				elseif m_selected2 == 7 then
					m_selected = 5
				end
			elseif m_selected < 7 and m_selected ~= 4 then
				m_selected = m_selected + 1
			end
			m_select()
		elseif menu_type == 'settings' then
			if cpick == 'Text Speed' and settings.textspd < 250 then
				settings.textspd = settings.textspd + 25
			elseif cpick == 'Auto-Forward Time' and settings.autospd < 15 then
				settings.autospd = settings.autospd + 1
			elseif cpick == 'Master Volume' and settings.masvol < 100 then
				settings.masvol = settings.masvol + 10
			elseif cpick == 'Music Volume' and settings.bgmvol < 100 then
				settings.bgmvol = settings.bgmvol + 10
			elseif cpick == 'Sound Volume' and settings.sfxvol < 100 then
				settings.sfxvol = settings.sfxvol + 10
			end
		end
		game_setvolume()
	
	elseif key == 'leftshoulder' or key == 'l' then
		if (menu_type == 'savegame' or menu_type == 'loadgame' or menu_type == 'settings') and pagenum > 1 then
			pagenum = pagenum - 1
			m_selected2 = m_selected
			menu_enable(menu_type)
			m_selected = m_selected2
		end
	
	elseif key == 'rightshoulder' or key == 'r' then
		if ((menu_type == 'savegame' or menu_type == 'loadgame') and pagenum < 10) or (menu_type == 'settings' and pagenum < 2) then
			pagenum = pagenum + 1
			m_selected2 = m_selected
			menu_enable(menu_type)
			m_selected = m_selected2
		end
		
	elseif key == 'y' then
		if menu_type == 'choice' and chapter < 5 and cl ~= 666 then
			menu_previous2 = 'choice'
			menu_alpha = 0
			menu_enable('pause')
		end
	end
end
