	elseif cl == 39 then
		cw('mc',"I'll look at a few clubs if it makes you happy.")
	elseif cl == 40 then 
		cw('mc',"No promises, though.")
	elseif cl == 41 then
		updateSayori('1','h')
		cw('s',"Will you at least promise me you'll try a little?")
	elseif cl == 42 then
		cw('mc',"Yeah, I guess I'll promise you that.")
	elseif cl == 43 then
		updateSayori('4','r')
		cw('s',"Yaay~!")
	elseif cl == 44 then
