function ch3_start_none()
	if cl < 87 then
		scriptJump(87)
	elseif cl == 87 then
		if audio1 ~= '3' then audioUpdate('0') end
		hideAll()
		bgUpdate('club')
		cw('bl',"...")
	elseif cl == 88 then
		audioUpdate('3')
		updateMonika('4','b',80)
		cw('m',"Okay, everyone!")
	elseif cl == 89 then
