		updateYuri('1','a',x)
		xaload = -1
	elseif y_gtimer > 0.9 and y_gtimer < 0.95  then
		updateYuri('0a','',x)
		xaload = -1
	elseif y_gtimer > 0.6 and y_gtimer < 0.65 then
		updateYuri('0b','',x)
		xaload = -1
	elseif y_gtimer < 0.1 then
		updateYuri('0a','',x)
		xaload = -1
	end
end

