				table.remove(monikatopics, 26)
				if persistent.chr.s ~= 6 then
					table.remove(monikatopics, 27)
				end
			end
		end
	elseif cl >= 205 and cl < 1050 then
		if monikatopic then loadstring('ch30_'..monikatopic..'()')() end
	end
	
	if cl >= 1050 then
		ch30_end()
	end
end

