		cw('n', "¿Por qué me miras así?")
	elseif cl == 766 then
		cw('n', "Si no te gusta, dímelo y ya está.")
	elseif cl == 767 then
		updateNatsuki('1','u')
		cw('n', "No me... cabrearé.")
