function ch2_s_med_shared()
	if cl <= 704 then
		scriptJump(705)
	elseif cl == 705 then
		updateSayori('1','a')
		cw('s', "Bueno, no se me da muy bien saber si un poema es bueno o malo...")
	elseif cl == 706 then
		cw('s', "Por eso hago lo que me dicta el corazón~")
