function poemgamekeypressed(key)
	if key == 'down' then
		if menuselected == 10 then
			menuselected = 6
		elseif menuselected == 5 then
			menuselected = 1
		elseif menuselected <= 9 then
			menuselected = menuselected + 1
		end
		menuselect()
		
	elseif key == 'up' then
		if menuselected == 1 then
			menuselected = 5
		elseif menuselected == 6 then
			menuselected = 10
		elseif menuselected >= 2 then
			menuselected = menuselected - 1
		end
		menuselect()
		
	elseif key == 'left' or key == 'right' then
		if menuselected <= 5 then
			menuselected = menuselected + 5
		elseif menuselected >= 6 then
			menuselected = menuselected - 5
		end
		menuselect()
	end
	
	if key == 'a' or key == 'leftshoulder' then
		if xaload >= 35 then
			if poemstate == 0 then
				poemstate = nil
				sfxplay2(sfx1)
			elseif poemword <= 19 then
				addpoints()
				updatewordlist()
				menuselect()
				xaload = 0
			elseif poemword == 20 then
				addpoints()
				poemgamefinish()
				xaload = -1
			end
		end
	elseif key == 'y' and eyes_in ~= true then
		menu_enable('pause')
	end
end	
